    21	    public void getOccupancyReport(Context ctx) {
    22	        String dateParam = ctx.queryParam("date");
    23	        if (dateParam == null) {
    24	            throw AppException.invalidRequest("Parâmetro 'date' é obrigatório");
    25	        }
    26	
    27	        LocalDate date;
    28	        try {
    29	            date = LocalDate.parse(dateParam, dateFormatter);
    30	        } catch (DateTimeParseException e) {
    31	            throw AppException.invalidRequest("Data inválida: " + dateParam);
    32	        }
    33	
    34	        String csv = reportService.generateOccupancyReport(date);
    35	        ctx.contentType("text/csv; charset=utf-8").result(csv);
