    17	public class ReservationController {
    18	    private final ReservationService reservationService;
    19	    private final ObjectMapper objectMapper;
    20	    private final DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    21	    private final DateTimeFormatter displayDateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    22	
    23	    public ReservationController(ReservationService reservationService, ObjectMapper objectMapper) {
    24	        this.reservationService = reservationService;
    25	        this.objectMapper = objectMapper;
    26	    }
    27	
    28	    public void createReservation(Context ctx) {
    29	        try {
    30	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
    31	
    32	            String roomNumber = getRequiredString(body, "roomNumber");
    33	            String guestName = getRequiredString(body, "guestName");
    34	            String guestEmail = getRequiredString(body, "guestEmail");
    35	            String guestCpf = getRequiredString(body, "guestCpf");
    36	            LocalDate checkIn = parseDate(getRequiredString(body, "checkIn"));
    37	            LocalDate checkOut = parseDate(getRequiredString(body, "checkOut"));
    38	            int guests = getRequiredInt(body, "guests");
    39	            RatePlan ratePlan = RatePlan.valueOf(getRequiredString(body, "ratePlan"));
    40	
    41	            Reservation reservation = reservationService.createReservation(
    42	                    roomNumber, guestName, guestEmail, guestCpf,
    43	                    checkIn, checkOut, guests, ratePlan);
    44	
    45	            ctx.status(201).json(reservationToMap(reservation));
    46	        } catch (IllegalArgumentException e) {
    47	            throw AppException.invalidRequest("Dados inválidos: " + e.getMessage());
    48	        }
    49	    }
    50	
    51	    public void getReservation(Context ctx) {
    52	        Long id = Long.parseLong(ctx.pathParam("id"));
    53	        Reservation reservation = reservationService.getReservation(id);
    54	        ctx.json(reservationToMap(reservation));
    55	    }
    56	
    57	    public void confirmReservation(Context ctx) {
    58	        Long id = Long.parseLong(ctx.pathParam("id"));
    59	        Reservation reservation = reservationService.confirmReservation(id);
    60	        ctx.json(reservationToMap(reservation));
    61	    }
    62	
    63	    public void cancelReservation(Context ctx) {
    64	        Long id = Long.parseLong(ctx.pathParam("id"));
    65	        Reservation reservation = reservationService.cancelReservation(id);
    66	        ctx.json(reservationToMap(reservation));
    67	    }
    68	
    69	    public void checkIn(Context ctx) {
    70	        Long id = Long.parseLong(ctx.pathParam("id"));
    71	        Reservation reservation = reservationService.checkIn(id);
    72	        ctx.json(reservationToMap(reservation));
    73	    }
    74	
    75	    public void checkOut(Context ctx) {
    76	        Long id = Long.parseLong(ctx.pathParam("id"));
    77	        Reservation reservation = reservationService.checkOut(id);
    78	        ctx.json(buildDocument(reservation));
    79	    }
    80	
    81	    public void getDocument(Context ctx) {
    82	        Long id = Long.parseLong(ctx.pathParam("id"));
    83	        Reservation reservation = reservationService.getReservation(id);
    84	
    85	        if (reservation.getAmountPaid().compareTo(BigDecimal.ZERO) == 0) {
    86	            throw AppException.operationNotAllowed("Documento só disponível para reservas pagas");
    87	        }
    88	
    89	        ctx.json(buildDocument(reservation));
    90	    }
    91	
    92	    private Map<String, Object> reservationToMap(Reservation r) {
    93	        Map<String, Object> map = new HashMap<>();
    94	        map.put("id", r.getId());
    95	        map.put("roomNumber", r.getRoomNumber());
    96	        map.put("guestName", r.getGuestName());
    97	        map.put("guestEmail", r.getGuestEmail());
    98	        map.put("guestCpf", r.getGuestCpf());
    99	        map.put("checkIn", r.getCheckIn().format(dateFormatter));
   100	        map.put("checkOut", r.getCheckOut().format(dateFormatter));
   101	        map.put("guests", r.getGuests());
   102	        map.put("ratePlan", r.getRatePlan().name());
   103	        map.put("nights", r.getNights());
   104	        map.put("subtotal", r.getSubtotal());
   105	        map.put("discount", r.getDiscount());
   106	        map.put("total", r.getTotal());
   107	        map.put("status", r.getStatus().name());
   108	        map.put("amountPaid", r.getAmountPaid());
   109	        map.put("refund", r.getRefund());
   110	        return map;
   111	    }
   112	
   113	    private Map<String, Object> buildDocument(Reservation r) {
   114	        Map<String, Object> doc = new HashMap<>();
   115	        doc.put("title", "Comprovante de reserva");
   116	        doc.put("reservationId", r.getId());
   117	        doc.put("guestName", r.getGuestName());
   118	        doc.put("guestCpf", r.getGuestCpf());
   119	        doc.put("roomNumber", r.getRoomNumber());
   120	        doc.put("roomType", getRoomTypeName(r.getRoomNumber()));
   121	        doc.put("checkIn", r.getCheckIn().format(displayDateFormatter));
   122	        doc.put("checkOut", r.getCheckOut().format(displayDateFormatter));
   123	        doc.put("nights", r.getNights());
   124	        doc.put("subtotal", r.getSubtotal());
   125	        doc.put("discount", r.getDiscount());
   126	        doc.put("total", r.getTotal());
   127	        return doc;
   128	    }
   129	
   130	    private String getRoomTypeName(String roomNumber) {
   131	        if (roomNumber.startsWith("1")) return "STANDARD";
   132	        if (roomNumber.startsWith("2")) return "DELUXE";
   133	        return "SUITE";
   134	    }
   135	
   136	    private String getRequiredString(Map<String, Object> map, String key) {
   137	        Object value = map.get(key);
   138	        if (value == null) {
   139	            throw AppException.invalidRequest("Campo obrigatório: " + key);
   140	        }
   141	        return value.toString();
   142	    }
   143	
   144	    private int getRequiredInt(Map<String, Object> map, String key) {
   145	        Object value = map.get(key);
   146	        if (value == null) {
   147	            throw AppException.invalidRequest("Campo obrigatório: " + key);
   148	        }
   149	        if (value instanceof Number) {
   150	            return ((Number) value).intValue();
   151	        }
   152	        try {
   153	            return Integer.parseInt(value.toString());
   154	        } catch (NumberFormatException e) {
   155	            throw AppException.invalidRequest("Valor inválido para " + key);
   156	        }
   157	    }
   158	
   159	    private LocalDate parseDate(String date) {
   160	        try {
   161	            return LocalDate.parse(date, dateFormatter);
   162	        } catch (DateTimeParseException e) {
   163	            throw AppException.invalidRequest("Data inválida: " + date);
   164	        }
   165	    }
   166	}
