    18	public class ReservationService {
    19	    private final ReservationRepository reservationRepository;
    20	    private final RoomService roomService;
    21	    private final PricingService pricingService;
    22	    private final EventPublisher eventPublisher;
    23	
    24	    public ReservationService(ReservationRepository reservationRepository,
    25	                            RoomService roomService,
    26	                            PricingService pricingService,
    27	                            EventPublisher eventPublisher) {
    28	        this.reservationRepository = reservationRepository;
