    33	
    34	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    35	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    36	                                        int guests, RatePlan ratePlan) {
    37	
    38	        Room room = roomService.getRoomByNumber(roomNumber);
    39	
    40	        validateReservation(room, checkIn, checkOut, guests, null);
    41	
    42	        Reservation reservation = new Reservation();
    43	        reservation.setRoomNumber(roomNumber);
    44	        reservation.setGuestName(guestName);
    45	        reservation.setGuestEmail(guestEmail);
    46	        reservation.setGuestCpf(guestCpf);
    47	        reservation.setCheckIn(checkIn);
    48	        reservation.setCheckOut(checkOut);
    49	        reservation.setGuests(guests);
    50	        reservation.setRatePlan(ratePlan);
    51	
    52	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    53	        reservation.setNights(nights);
    54	
    55	        BigDecimal subtotal = pricingService.calculateSubtotal(room.getType(), checkIn, checkOut);
    56	        reservation.setSubtotal(subtotal);
    57	
    58	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
    59	        reservation.setDiscount(discount);
    60	
    61	        BigDecimal total = subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
    62	        reservation.setTotal(total);
    63	
    64	        return reservationRepository.save(reservation);
    65	    }
