    72	    public Reservation confirmReservation(Long id) {
    73	        Reservation reservation = getReservation(id);
    74	
    75	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    76	            throw AppException.operationNotAllowed("Só é possível confirmar uma reserva pendente");
    77	        }
    78	
    79	        reservation.setStatus(ReservationStatus.CONFIRMED);
    80	        reservation.setAmountPaid(reservation.getTotal());
    81	        Reservation updated = reservationRepository.save(reservation);
    82	
    83	        eventPublisher.publish(new ReservationConfirmedEvent(updated));
    84	
    85	        return updated;
    86	    }
    87	
    88	    public Reservation cancelReservation(Long id) {
    89	        Reservation reservation = getReservation(id);
    90	
    91	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
    92	            reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
    93	            reservation.getStatus() == ReservationStatus.CANCELLED) {
    94	            throw AppException.operationNotAllowed("Não é possível cancelar esta reserva");
    95	        }
    96	
    97	        boolean wasConfirmed = reservation.getStatus() == ReservationStatus.CONFIRMED;
    98	
    99	        BigDecimal refund = BigDecimal.ZERO;
   100	        if (reservation.getRatePlan() == RatePlan.STANDARD && wasConfirmed) {
   101	            refund = reservation.getAmountPaid();
   102	        }
   103	
   104	        reservation.setStatus(ReservationStatus.CANCELLED);
   105	        reservation.setRefund(refund);
   106	        Reservation updated = reservationRepository.save(reservation);
   107	
   108	        eventPublisher.publish(new ReservationCancelledEvent(updated, wasConfirmed));
   109	
   110	        return updated;
   111	    }
   112	
   113	    public Reservation checkIn(Long id) {
   114	        Reservation reservation = getReservation(id);
   115	
   116	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   117	            throw AppException.operationNotAllowed("Só é possível fazer check-in de uma reserva confirmada");
   118	        }
   119	
   120	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   121	        return reservationRepository.save(reservation);
   122	    }
   123	
   124	    public Reservation checkOut(Long id) {
   125	        Reservation reservation = getReservation(id);
   126	
   127	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   128	            throw AppException.operationNotAllowed("Só é possível fazer check-out de uma reserva com check-in feito");
   129	        }
   130	
   131	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   132	        return reservationRepository.save(reservation);
   133	    }
   134	
   135	    private void validateReservation(Room room, LocalDate checkIn, LocalDate checkOut,
   136	                                    int guests, Long excludeId) {
   137	        if (guests < 1) {
   138	            throw AppException.invalidRequest("A reserva deve ter pelo menos um hóspede");
   139	        }
   140	
   141	        if (guests > room.getCapacity()) {
   142	            throw AppException.capacityExceeded();
   143	        }
   144	
   145	        if (!checkOut.isAfter(checkIn)) {
   146	            throw AppException.invalidRequest("A data de saída deve ser posterior à data de entrada");
   147	        }
   148	
   149	        if (reservationRepository.hasConflictingReservation(room.getNumber(), checkIn, checkOut, excludeId)) {
   150	            throw AppException.roomUnavailable();
   151	        }
   152	    }
   153	}
