    10	public class PricingService {
    11	
    12	    public BigDecimal calculateSubtotal(RoomType roomType, LocalDate checkIn, LocalDate checkOut) {
    13	        BigDecimal nightlyRate = roomType.getNightlyRate();
    14	        BigDecimal subtotal = BigDecimal.ZERO;
    15	
    16	        LocalDate current = checkIn;
    17	        while (current.isBefore(checkOut)) {
    18	            BigDecimal nightPrice = nightlyRate;
    19	            if (isHighSeason(current)) {
    20	                nightPrice = nightPrice.multiply(new BigDecimal("1.20"))
    21	                        .setScale(2, RoundingMode.HALF_EVEN);
    22	            }
    23	            subtotal = subtotal.add(nightPrice);
    24	            current = current.plusDays(1);
    25	        }
    26	
    27	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
    28	    }
    29	
    30	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    31	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    32	            return subtotal.multiply(new BigDecimal("0.15"))
    33	                    .setScale(2, RoundingMode.HALF_EVEN);
    34	        }
    35	        return BigDecimal.ZERO;
    36	    }
    37	
    38	    private boolean isHighSeason(LocalDate date) {
    39	        int month = date.getMonthValue();
    40	        int day = date.getDayOfMonth();
    41	
    42	        if (month == 7) {
    43	            return true;
    44	        }
    45	
    46	        if (month == 12 && day >= 15) {
    47	            return true;
    48	        }
    49	
    50	        if (month == 1 || month == 2) {
    51	            return true;
    52	        }
    53	
    54	        return false;
    55	    }
    56	}
