     7	
     8	public class EventPublisher {
     9	    private final Map<Class<? extends ReservationEvent>, List<EventListener<?>>> listeners = new HashMap<>();
    10	
    11	    public <T extends ReservationEvent> void subscribe(Class<T> eventType, EventListener<T> listener) {
    12	        listeners.computeIfAbsent(eventType, k -> new ArrayList<>()).add(listener);
    13	    }
    14	
    15	    @SuppressWarnings("unchecked")
    16	    public <T extends ReservationEvent> void publish(T event) {
    17	        List<EventListener<?>> eventListeners = listeners.get(event.getClass());
    18	        if (eventListeners != null) {
    19	            for (EventListener<?> listener : eventListeners) {
    20	                ((EventListener<T>) listener).handle(event);
    21	            }
    22	        }
    23	    }
    24	}
