    14	public class GuestNotificationListener implements EventListener<ReservationConfirmedEvent> {
    15	    private final NotificationService notificationService;
    16	    private final DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    17	    private final DecimalFormat moneyFormatter;
    18	
    19	    public GuestNotificationListener(NotificationService notificationService) {
    20	        this.notificationService = notificationService;
    21	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(new Locale("pt", "BR"));
    22	        symbols.setDecimalSeparator(',');
    23	        symbols.setGroupingSeparator('.');
    24	        this.moneyFormatter = new DecimalFormat("#,##0.00", symbols);
    25	    }
    26	
    27	    @Override
    28	    public void handle(ReservationConfirmedEvent event) {
    29	        Reservation reservation = event.getReservation();
    30	
    31	        String receipt = buildReceipt(reservation);
    32	        String subject = "Reserva confirmada - Pousada Maré Alta";
    33	        String body = String.format("""
    34	                Olá, %s!
    35	
    36	                Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
    37	
    38	                %s
    39	
    40	                A entrada é a partir das 14h, e a saída, até as 12h.
    41	                Até breve!""", reservation.getGuestName(), receipt);
    42	
    43	        notificationService.sendEmail(reservation.getGuestEmail(), subject, body);
    44	    }
    45	
    46	    private String buildReceipt(Reservation reservation) {
    47	        StringBuilder sb = new StringBuilder();
    48	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    49	        sb.append("Hóspede: ").append(reservation.getGuestName())
    50	          .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
    51	        sb.append("Quarto: ").append(reservation.getRoomNumber())
    52	          .append(" (").append(reservation.getRoomNumber().startsWith("1") ? "STANDARD" :
    53	                              reservation.getRoomNumber().startsWith("2") ? "DELUXE" : "SUITE").append(")\n");
    54	        sb.append("Entrada: ").append(reservation.getCheckIn().format(dateFormatter))
    55	          .append(" | Saída: ").append(reservation.getCheckOut().format(dateFormatter))
    56	          .append(" | ").append(reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias").append("\n");
    57	        sb.append("Diárias: R$ ").append(formatMoney(reservation.getSubtotal())).append("\n");
    58	
    59	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    60	            sb.append("Desconto: R$ ").append(formatMoney(reservation.getDiscount())).append("\n");
    61	        }
    62	
    63	        sb.append("Total: R$ ").append(formatMoney(reservation.getTotal()));
    64	
    65	        return sb.toString();
    66	    }
    67	
    68	    private String formatCpf(String cpf) {
    69	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    70	               cpf.substring(6, 9) + "-" + cpf.substring(9, 11);
    71	    }
